package org.sleepwell.app;

import org.junit.Test;import static org.junit.Assert.*;import java.util.*;

public final class ChallengeCountingFlagsTest {
    @Test public void stableCountingBoardsHaveOneTypedNumericalAnswer(){for(int round=0;round<6;round++)for(int unit=0;unit<150;unit++){CountingPuzzle a=CountingPuzzle.create("run",unit,round),b=CountingPuzzle.create("run",unit,round);assertEquals(a.target,b.target);assertEquals(a.size(),b.size());for(int n=0;n<a.size();n++)assertEquals(a.shape(n),b.shape(n));assertTrue(a.answer()>0);assertTrue(a.accepts(""+a.answer()));assertTrue(a.accepts("  "+a.answer()+" "));assertFalse(a.accepts(""+(a.answer()+1)));assertFalse(a.accepts("1.0"));assertFalse(a.accepts("+"+a.answer()));}}
    @Test public void originalPackVariesAcrossOwnersAndAllShapesAppear(){Set<String> signatures=new HashSet<>();Set<Integer> targets=new HashSet<>();for(int n=0;n<100;n++){CountingPuzzle a=CountingPuzzle.create("occurrence-"+n,0,0);targets.add(a.target);StringBuilder key=new StringBuilder();for(int cell=0;cell<a.size();cell++)key.append(a.shape(cell));signatures.add(key.toString());}assertEquals(3,targets.size());assertTrue(signatures.size()>90);}
    @Test public void eachFlagQuestionHasFourUniqueChoicesAndOneCorrectAnswer(){Set<Integer> countries=new HashSet<>();for(int n=0;n<500;n++){FlagPuzzle a=FlagPuzzle.create("run-"+n,0,n%6),b=FlagPuzzle.create("run-"+n,0,n%6);countries.add(a.target);assertEquals(a.target,b.target);assertEquals(a.choices,b.choices);assertEquals(4,new HashSet<>(a.choices).size());int correct=0;for(int choice:a.choices)if(a.accepts(choice))correct++;assertEquals(1,correct);assertFalse(a.accepts(-1));assertFalse(a.accepts(100));}assertEquals(FlagPuzzle.COUNTRIES.size(),countries.size());}
    @Test public void ownerAndRoundBoundsCannotCreateUnboundedBoards(){for(String run:new String[]{null,"","x".repeat(129)})assertThrows(IllegalArgumentException.class,()->CountingPuzzle.create(run,0,0));assertThrows(IllegalArgumentException.class,()->CountingPuzzle.create("run",-1,0));assertThrows(IllegalArgumentException.class,()->FlagPuzzle.create("run",0,6));assertThrows(IllegalArgumentException.class,()->FlagPuzzle.create("run",0,-1));}
}
